const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-height:0;min-width:0;padding:10px;overflow:hidden;color:var(--ink);font-size:12px;line-height:1.35;font-variant-numeric:tabular-nums}\n.card *{box-sizing:border-box}\n.card h3{margin:0;font-size:13px;font-weight:700;color:var(--ink)}\n.card p{margin:0}\n.card[data-size=\"3x3\"]{padding:8px;font-size:11px}\n.view{display:flex;flex-direction:column;gap:8px;height:100%;min-height:0;min-width:0}\n.view.home{gap:6px}\n.card[data-size=\"6x3\"] .view.home{flex-direction:row;gap:12px}\n\n/* buttons */\n.btn{border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);border-radius:8px;padding:5px 10px;min-height:30px;font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.sm{min-height:28px;padding:3px 9px}\n.btn.sq{min-width:32px;padding:3px 0}\n.btn.big{min-height:40px;font-size:14px;padding:6px 16px}\n.btn:disabled{opacity:.45;cursor:default}\n.btn:focus-visible,.chip:focus-visible,.tab:focus-visible,.lrow:focus-visible,.inp:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n/* header */\n.head{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"k a\" \"b b\";align-items:center;gap:2px 6px;flex:0 0 auto;min-width:0}\n.kicker{grid-area:k;color:var(--muted);font-size:11px;min-width:0}\n.head .add{grid-area:a}\n.bigrow{grid-area:b;display:flex;align-items:center;gap:8px;min-width:0}\n.big{font-size:28px;font-weight:700;line-height:1.1;white-space:nowrap;color:var(--ink)}\n.big small{font-size:12px;font-weight:400;color:var(--muted)}\n.metas{display:flex;flex-direction:column;min-width:0;font-size:11px;color:var(--muted);line-height:1.3}\n.card[data-size=\"3x3\"] .big{font-size:24px}\n.card[data-size=\"3x3\"] .head .add{min-height:26px;padding:2px 8px}\n.card[data-size=\"6x6\"] .big{font-size:34px}\n.card[data-size=\"6x3\"] .head{flex:0 0 34%;grid-template-columns:minmax(0,1fr);grid-template-areas:\"k\" \"b\" \"a\";align-content:space-between;gap:6px}\n.card[data-size=\"6x3\"] .bigrow{flex-direction:column;align-items:flex-start;gap:4px}\n.card[data-size=\"6x3\"] .head .add{align-self:end;width:100%}\n\n/* main / tabs / body */\n.main{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.tabs{display:flex;gap:4px;flex:0 0 auto}\n.tab{flex:1;min-width:0;border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:8px;padding:3px 2px;min-height:28px;font:inherit;cursor:pointer}\n.tab[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.body{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:14px;padding-right:2px}\n.body>*{flex:0 0 auto}\n.sec{display:flex;flex-direction:column;gap:6px;min-width:0}\n.sh{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;min-width:0}\n.card[data-size=\"3x3\"] .sec>.sh>h3,.card[data-size=\"6x3\"] .sec>.sh>h3{display:none}\n.card[data-size=\"3x3\"] .sec>.sh:empty{display:none}\n.chips{display:flex;gap:3px;flex-wrap:wrap}\n.chip{border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:999px;padding:2px 9px;min-height:26px;font:inherit;font-size:11px;cursor:pointer;white-space:nowrap}\n.chip[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.hint{color:var(--muted);font-size:11px;line-height:1.4;overflow-wrap:anywhere}\n.muted{color:var(--muted)}\n\n/* chart */\n.chartbox{min-width:0;overflow:hidden}\n.chart{display:block;max-width:100%;height:auto}\n.gl{stroke:var(--line);stroke-width:1}\n.axl{fill:var(--muted);font-size:9px}\n.vl{fill:var(--ink);font-size:10px;font-weight:600}\n.sline{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round;stroke-linecap:round}\n.tline{fill:none;stroke:var(--accent-alt);stroke-width:1.5;stroke-dasharray:4 3}\n.ttick{stroke:var(--accent-alt);stroke-width:2}\n.pt{fill:var(--paper);stroke:var(--accent);stroke-width:2}\n.pt.on{fill:var(--accent)}\n.hit{fill:transparent;cursor:pointer}\n.legend{display:flex;gap:12px;font-size:10px;color:var(--muted)}\n.lg{display:inline-flex;align-items:center;gap:4px}\n.lg::before{content:\"\";display:inline-block;width:16px;height:0;border-top:2px solid var(--accent)}\n.lg.l2::before{border-top:2px dashed var(--accent-alt)}\n.selbox{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--soft);min-width:0}\n.sbt{min-width:0;flex:1}\n.sb1{font-weight:700;font-size:12px}\n.sb2{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n\n/* parts */\n.picker{display:flex;align-items:center;gap:6px}\n.pk{flex:1;min-width:0;text-align:center;font-weight:600;overflow-wrap:anywhere}\n.bars{display:flex;flex-direction:column;gap:10px;min-width:0}\n.prow{display:flex;flex-direction:column;gap:4px;min-width:0}\n.pl1{display:flex;align-items:baseline;gap:8px;min-width:0}\n.pn{flex:1;min-width:0;font-weight:600;overflow-wrap:anywhere}\n.ps{font-size:14px;white-space:nowrap}\n.pd{font-size:11px;color:var(--muted);white-space:nowrap}\n.track{position:relative;height:8px;border-radius:4px;background:var(--soft)}\n.fill{height:100%;width:0;border-radius:4px;background:var(--accent)}\n.tick{position:absolute;top:-3px;width:2px;height:14px;margin-left:-1px;border-radius:1px;background:var(--ink)}\n.psub{font-size:10px;color:var(--muted);overflow-wrap:anywhere}\n.tblwrap{display:flex;flex-direction:column;gap:6px;min-width:0}\n.tw{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:8px}\n.tbl{border-collapse:collapse;font-size:11px;white-space:nowrap}\n.tbl th,.tbl td{padding:5px 8px;border-bottom:1px solid var(--line);text-align:right}\n.tbl th:first-child{text-align:left;font-weight:600}\n.tbl thead th{color:var(--muted);font-weight:500}\n.tbl tr:last-child th,.tbl tr:last-child td{border-bottom:0}\n.tbl .chg{color:var(--ink);font-weight:600}\n\n/* list */\n.list{display:flex;flex-direction:column;gap:6px;min-width:0}\n.lrow{display:flex;flex-direction:column;gap:2px;width:100%;min-width:0;text-align:left;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--button-paper,var(--paper));color:var(--ink);font:inherit;cursor:pointer}\n.lr1{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-width:0}\n.ld{font-weight:600;min-width:0}\n.lt{white-space:nowrap;font-size:13px}\n.lr2{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n\n/* form */\n.view.form,.view.detail{gap:6px}\n.ftitle{flex:0 0 auto}\n.fbody,.dbody{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.fbody>*,.dbody>*{flex:0 0 auto}\n.lab{display:flex;flex-direction:column;gap:2px;min-width:0}\n.lab>span{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-width:0;height:32px;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.inp::-webkit-outer-spin-button,.inp::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n.inp[type=number]{-moz-appearance:textfield}\n.g2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}\n.srows{display:flex;flex-direction:column;gap:8px;min-width:0}\n.srow{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"n x\" \"v v\";gap:6px;padding:7px;border:1px solid var(--line);border-radius:10px;background:var(--soft);min-width:0}\n.srow .n{grid-area:n}\n.srow .v{grid-area:v;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}\n.srow .x{grid-area:x;align-self:end}\n.srow .inp{padding:4px 5px}\n.card[data-size=\"6x3\"] .srow,.card[data-size=\"6x6\"] .srow{grid-template-columns:minmax(0,1.3fr) minmax(0,2.2fr) auto;grid-template-areas:\"n v x\"}\n.err{display:none;padding:6px 8px;border:1px solid var(--line);border-left:3px solid var(--accent);border-radius:6px;background:var(--soft);color:var(--ink);font-size:12px;overflow-wrap:anywhere}\n.foot{display:flex;align-items:center;gap:8px;flex:0 0 auto}\n.foot .btn{flex:1}\n.foot .ask{flex:2;font-size:11px;color:var(--ink)}\n\n/* detail */\n.dhead{display:flex;align-items:center;gap:8px;flex:0 0 auto}\n.dt{font-weight:700;font-size:13px;min-width:0;overflow-wrap:anywhere}\n.dsum{display:flex;align-items:center;gap:10px;min-width:0}\n\n/* empty */\n.view.empty{justify-content:center;align-items:flex-start;gap:8px}\n.view.empty h3{font-size:15px}\n.view.empty .btn{align-self:stretch}\n.card[data-size=\"3x3\"] .view.empty p.muted{display:none}\n";
function num(v){
  if(v===null||v===undefined)return null;
  if(typeof v==='string'&&v.trim()==='')return null;
  var n=Number(v);
  return isFinite(n)?n:null;
}
function rnd(n){return Math.round(n*100)/100;}
function fmt(n){return (n===null||n===undefined||!isFinite(n))?'—':String(rnd(n));}
function dtext(d){
  var r=rnd(d);
  if(r>0)return '▲ '+fmt(r);
  if(r<0)return '▼ '+fmt(-r);
  return '＝ 持平';
}
function dparts(d){
  var p=String(d||'').split('-');
  return p.length===3?{y:Number(p[0]),m:Number(p[1]),d:Number(p[2])}:null;
}
function shortDate(d){var p=dparts(d);return p?p.m+'/'+p.d:String(d||'');}
function longDate(d){var p=dparts(d);return p?p.y+'年'+p.m+'月'+p.d+'日':String(d||'');}
function key(n){return String(n===undefined||n===null?'':n).trim();}
function sortExams(s){
  var src=(s&&Array.isArray(s.exams))?s.exams:[];
  var a=src.map(function(e,i){return {e:e,i:i};});
  a.sort(function(x,y){
    if(x.e.date<y.e.date)return -1;
    if(x.e.date>y.e.date)return 1;
    return x.i-y.i;
  });
  return a.map(function(x){return x.e;});
}
function secOf(e,name){
  var rs=(e&&e.rows)||[];
  for(var i=0;i<rs.length;i++){if(key(rs[i].name)===key(name))return rs[i];}
  return null;
}
function prevOfSec(list,idx,name){
  for(var i=idx-1;i>=0;i--){var r=secOf(list[i],name);if(r)return r;}
  return null;
}
function metric(r){
  if(r.full>0)return {k:'full',v:r.score/r.full};
  if(r.target>0)return {k:'target',v:r.score/r.target};
  return null;
}
function scaleOf(rows){
  var m=0;
  rows.forEach(function(r){var d=r.full>0?r.full:r.score;if(d>m)m=d;});
  return m||1;
}
function barFrac(v,r,scale){
  var d=r.full>0?r.full:scale;
  return Math.max(0,Math.min(1,v/d));
}
function axisNum(v,span){return span<20?Math.round(v*10)/10:Math.round(v);}
function sv(tag,attrs){
  var n=document.createElementNS('http://www.w3.org/2000/svg',tag);
  if(attrs){
    for(var k in attrs){
      var v=attrs[k];
      if(v===null||v===undefined)continue;
      if(k==='onclick'){n.addEventListener('click',v);}
      else n.setAttribute(k,String(v));
    }
  }
  for(var i=2;i<arguments.length;i++){
    var c=arguments[i];
    if(c===null||c===undefined||c===false)continue;
    n.appendChild(typeof c==='object'?c:document.createTextNode(String(c)));
  }
  return n;
}


function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const sz=ctx.size||root.getAttribute('data-size')||'3x3';
  const exams=sortExams(state);
  const small=(sz==='3x3'||sz==='6x3');
  if(!ui.mode)ui.mode='home';
  if(!ui.tab)ui.tab='trend';
  if(!ui.range)ui.range='5';
  if(!ui.pmode)ui.pmode='one';
  const last=exams.length?exams[exams.length-1]:null;
  function byId(id){for(let i=0;i<exams.length;i++){if(exams[i].id===id)return exams[i];}return null;}
  const sel=byId(ui.sel)||last;
  const selIdx=sel?exams.indexOf(sel):-1;

  function box(tag,attrs,kids){
    const n=el(tag,attrs||{});
    kids.forEach(k=>{if(k)n.appendChild(k);});
    return n;
  }
  function go(patch){Object.assign(ui,patch);redraw();}
  function btn(label,onclick,cls,disabled,aria){
    const a={type:'button',class:'btn '+(cls||''),onclick:onclick};
    if(disabled)a.disabled=true;
    if(aria)a['aria-label']=aria;
    return el('button',a,label);
  }
  function chipSet(opts,cur,onPick){
    return box('div',{class:'chips'},opts.map(o=>{
      const a={type:'button',class:'chip','aria-pressed':String(cur===o[0]),onclick:()=>onPick(o[0])};
      return el('button',a,o[1]);
    }));
  }
  function gapText(e){
    if(e.target===null||e.target===undefined)return '未设目标分';
    const d=e.total-e.target;
    return d>=0?('目标 '+fmt(e.target)+' · 已达成，超出 '+fmt(d)):('目标 '+fmt(e.target)+' · 还差 '+fmt(-d));
  }
  function chgText(e){
    const i=exams.indexOf(e);
    if(i<=0)return '首次记录';
    return '较上次 '+dtext(e.total-exams[i-1].total);
  }
  function openDetail(e){go({mode:'detail',detailId:e.id,confirmDel:false});}

  /* ---------- 总分趋势图 ---------- */
  function chart(list){
    const dims={'3x3':[172,78],'6x3':[232,104],'3x6':[172,132],'6x6':[372,158]}[sz]||[172,100];
    const W=dims[0],H=dims[1],pl=30,pr=12,pt=16,pb=18;
    const n=list.length;
    const all=list.map(e=>e.total);
    list.forEach(e=>{if(e.target!==null&&e.target!==undefined)all.push(e.target);});
    const mn=Math.min.apply(null,all),mx=Math.max.apply(null,all);
    let lo=mn,hi=mx;
    if(hi===lo){const h=Math.max(5,Math.abs(hi)*0.05);lo-=h;hi+=h;}
    else{const p=(hi-lo)*0.18;lo-=p;hi+=p;}
    if(lo<0&&mn>=0)lo=0;
    const span=hi-lo;
    const X=i=>n===1?pl+(W-pl-pr)/2:pl+i*(W-pl-pr)/(n-1);
    const Y=v=>pt+(H-pt-pb)*(1-(v-lo)/span);
    const svg=sv('svg',{viewBox:'0 0 '+W+' '+H,width:W,height:H,class:'chart',role:'img','aria-label':'总分变化图'});
    const add=k=>svg.appendChild(k);
    [0,0.5,1].forEach(t=>{
      const v=lo+span*t;
      add(sv('line',{class:'gl',x1:pl,x2:W-pr,y1:Y(v),y2:Y(v)}));
      add(sv('text',{class:'axl',x:pl-4,y:Y(v)+3,'text-anchor':'end'},String(axisNum(v,span))));
    });
    let td='',prevHas=false;
    list.forEach((e,i)=>{
      if(e.target!==null&&e.target!==undefined){td+=(prevHas?'L':'M')+X(i)+' '+Y(e.target)+' ';prevHas=true;}
      else prevHas=false;
    });
    if(td)add(sv('path',{class:'tline',d:td}));
    list.forEach((e,i)=>{
      if(e.target!==null&&e.target!==undefined)add(sv('line',{class:'ttick',x1:X(i)-7,x2:X(i)+7,y1:Y(e.target),y2:Y(e.target)}));
    });
    if(n>1)add(sv('path',{class:'sline',d:list.map((e,i)=>(i?'L':'M')+X(i)+' '+Y(e.total)).join(' ')}));
    const every=n<=6;
    const maxLab=Math.max(2,Math.floor((W-pl-pr)/36));
    const stepL=Math.ceil(n/maxLab);
    list.forEach((e,i)=>{
      const on=!!sel&&e.id===sel.id;
      add(sv('circle',{class:'pt'+(on?' on':''),cx:X(i),cy:Y(e.total),r:on?5:3.5}));
      if(every||on||i===n-1)add(sv('text',{class:'vl',x:X(i),y:Y(e.total)-8,'text-anchor':'middle'},fmt(e.total)));
      if((n-1-i)%stepL===0||on)add(sv('text',{class:'axl',x:X(i),y:H-4,'text-anchor':'middle'},shortDate(e.date)));
    });
    list.forEach((e,i)=>{
      add(sv('circle',{class:'hit',cx:X(i),cy:Y(e.total),r:13,onclick:()=>go({sel:e.id})}));
    });
    return svg;
  }

  function trendSec(){
    const sec=el('section',{class:'sec'});
    const head=box('div',{class:'sh'},[
      el('h3',{},'总分变化'),
      exams.length>5?chipSet([['5','近5次'],['10','近10次'],['all','全部']],ui.range,v=>go({range:v})):null
    ]);
    sec.appendChild(head);
    const cnt=ui.range==='all'?exams.length:Number(ui.range);
    const list=exams.slice(Math.max(0,exams.length-cnt));
    sec.appendChild(el('div',{class:'chartbox'},chart(list)));
    sec.appendChild(box('div',{class:'legend'},[
      el('span',{class:'lg l1'},'总分'),
      el('span',{class:'lg l2'},'目标分')
    ]));
    if(exams.length===1){
      sec.appendChild(el('div',{class:'hint'},'目前只有 1 次成绩。再记录一次，就能看到总分的升降和趋势。'));
    }else if(list.length>1){
      const a=list[0],b=list[list.length-1];
      sec.appendChild(el('div',{class:'hint'},'最近 '+list.length+' 次：'+fmt(a.total)+' → '+fmt(b.total)+'（'+dtext(b.total-a.total)+'）'));
    }
    if(sel){
      sec.appendChild(box('div',{class:'selbox'},[
        box('div',{class:'sbt'},[
          el('div',{class:'sb1'},longDate(sel.date)+' · '+fmt(sel.total)+' 分'),
          el('div',{class:'sb2'},gapText(sel)+' · '+chgText(sel))
        ]),
        btn('详情',()=>openDetail(sel),'sm')
      ]));
    }
    return sec;
  }


  /* ---------- 各部分 ---------- */
  function barRows(e){
    const rows=e.rows||[];
    const wrap=el('div',{class:'bars'});
    if(!rows.length){
      wrap.appendChild(el('div',{class:'hint'},'这次没有填写各部分分数。'));
      wrap.appendChild(btn('补充各部分分数',()=>openEdit(e),'sm'));
      return wrap;
    }
    const idx=exams.indexOf(e);
    const scale=scaleOf(rows);
    let anyPrev=false;
    rows.forEach(r=>{
      const pv=prevOfSec(exams,idx,r.name);
      if(pv)anyPrev=true;
      const sub=[];
      if(r.full>0)sub.push('满分 '+fmt(r.full)+' · 得分率 '+Math.round(r.score/r.full*100)+'%');
      if(r.target!==null&&r.target!==undefined){
        const d=r.score-r.target;
        sub.push(d>=0?('目标 '+fmt(r.target)+' 已达成'):('目标 '+fmt(r.target)+' 差 '+fmt(-d)));
      }
      const fill=el('div',{class:'fill'});
      fill.style.width=(barFrac(r.score,r,scale)*100)+'%';
      const track=el('div',{class:'track'},fill);
      if(r.target!==null&&r.target!==undefined){
        const tk=el('i',{class:'tick'});
        tk.style.left=(barFrac(r.target,r,scale)*100)+'%';
        track.appendChild(tk);
      }
      wrap.appendChild(box('div',{class:'prow'},[
        box('div',{class:'pl1'},[
          el('span',{class:'pn'},key(r.name)),
          el('b',{class:'ps'},fmt(r.score)),
          pv?el('span',{class:'pd',title:'较上次'},dtext(r.score-pv.score)):null
        ]),
        track,
        sub.length?el('div',{class:'psub'},sub.join(' · ')):null
      ]));
    });
    const ms=rows.map(r=>({r:r,m:metric(r)})).filter(x=>x.m);
    const gf=ms.filter(x=>x.m.k==='full'),gt=ms.filter(x=>x.m.k==='target');
    const grp=gf.length>=2?gf:(gt.length>=2?gt:null);
    if(grp){
