      if(!date)return setErr('请选择日期');
      const total=num(d.total);
      if(total===null||total<0)return setErr('请填写有效的总分（数字，不小于 0）');
      let tg=null;
      if(str(d.target).trim()!==''){
        tg=num(d.target);
        if(tg===null||tg<0)return setErr('目标分请填写数字');
      }
      const rows=[],seen=[];
      for(let i=0;i<d.rows.length;i++){
        const r=d.rows[i];
